#include "check.h"

uint32_t lzma_crc32_table[8][256];
uint32_t lzma_crc64_table[8][256];

void lzma_crc32_init(void)
{
    for (uint32_t b = 0; b < 256; b++) {
        uint32_t r = b;
        for (int i = 0; i < 8; i++)
            r = (r >> 1) ^ ((r & 1) ? UINT32_C(0xEDB88320) : 0);
        lzma_crc32_table[0][b] = r;
    }
    for (int s = 1; s < 8; s++)
        for (int b = 0; b < 256; b++)
            lzma_crc32_table[s][b] = (lzma_crc32_table[s-1][b] >> 8)
                    ^ lzma_crc32_table[0][lzma_crc32_table[s-1][b] & 0xFF];
}

void lzma_crc64_init(void)
{
    for (uint32_t b = 0; b < 256; b++) {
        uint64_t r = b;
        for (int i = 0; i < 8; i++)
            r = (r >> 1) ^ ((r & 1) ? UINT64_C(0xC96C5795D7870F42) : 0);
        lzma_crc64_table[0][b] = r;
    }
    for (int s = 1; s < 8; s++)
        for (int b = 0; b < 256; b++)
            lzma_crc64_table[s][b] = (lzma_crc64_table[s-1][b] >> 8)
                    ^ lzma_crc64_table[0][lzma_crc64_table[s-1][b] & 0xFF];
}

uint32_t lzma_crc32(const uint8_t *buf, size_t size, uint32_t crc)
{
    crc = ~crc;
    while (size != 0) {
        crc = lzma_crc32_table[0][(*buf++) ^ (crc & 0xFF)] ^ (crc >> 8);
        size--;
    }
    return ~crc;
}

uint64_t lzma_crc64(const uint8_t *buf, size_t size, uint64_t crc)
{
    crc = ~crc;
    while (size != 0) {
        crc = lzma_crc64_table[0][(*buf++) ^ (crc & 0xFF)] ^ (crc >> 8);
        size--;
    }
    return ~crc;
}

// SHA-256
static const uint32_t sha256_k[64] = {
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1,
    0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
    0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
    0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
    0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
    0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
    0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
    0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
};

static void sha256_transform(lzma_sha256_state *s, const uint8_t *buf)
{
    uint32_t w[64];
    for (int i = 0; i < 16; i++)
        w[i] = ((uint32_t)buf[i*4] << 24) | ((uint32_t)buf[i*4+1] << 16)
             | ((uint32_t)buf[i*4+2] << 8) | (uint32_t)buf[i*4+3];
    for (int i = 16; i < 64; i++) {
        uint32_t s0 = ((w[i-15] >> 7) | (w[i-15] << 25)) ^ ((w[i-15] >> 18) | (w[i-15] << 14)) ^ (w[i-15] >> 3);
        uint32_t s1 = ((w[i-2] >> 17) | (w[i-2] << 15)) ^ ((w[i-2] >> 19) | (w[i-2] << 13)) ^ (w[i-2] >> 10);
        w[i] = w[i-16] + s0 + w[i-7] + s1;
    }
    uint32_t a = s->state[0], b = s->state[1], c = s->state[2], d = s->state[3];
    uint32_t e = s->state[4], f = s->state[5], g = s->state[6], h = s->state[7];
    for (int i = 0; i < 64; i++) {
        uint32_t S1 = ((e >> 6) | (e << 26)) ^ ((e >> 11) | (e << 21)) ^ ((e >> 25) | (e << 7));
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t t1 = h + S1 + ch + sha256_k[i] + w[i];
        uint32_t S0 = ((a >> 2) | (a << 30)) ^ ((a >> 13) | (a << 19)) ^ ((a >> 22) | (a << 10));
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t t2 = S0 + maj;
        h = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
    }
    s->state[0] += a; s->state[1] += b; s->state[2] += c; s->state[3] += d;
    s->state[4] += e; s->state[5] += f; s->state[6] += g; s->state[7] += h;
}

void lzma_sha256_init(lzma_sha256_state *s)
{
    s->state[0] = 0x6a09e667; s->state[1] = 0xbb67ae85;
    s->state[2] = 0x3c6ef372; s->state[3] = 0xa54ff53a;
    s->state[4] = 0x510e527f; s->state[5] = 0x9b05688c;
    s->state[6] = 0x1f83d9ab; s->state[7] = 0x5be0cd19;
    s->size = 0;
    s->buf_size = 0;
}

void lzma_sha256_update(lzma_sha256_state *s, const uint8_t *buf, size_t size)
{
    s->size += size;
    if (s->buf_size != 0) {
        size_t need = 64 - s->buf_size;
        size_t take = need < size ? need : size;
        for (size_t i = 0; i < take; i++) s->buf[s->buf_size + i] = buf[i];
        s->buf_size += take;
        buf += take;
        size -= take;
        if (s->buf_size == 64) {
            sha256_transform(s, s->buf);
            s->buf_size = 0;
        }
    }
    while (size >= 64) {
        sha256_transform(s, buf);
        buf += 64;
        size -= 64;
    }
    for (size_t i = 0; i < size; i++) s->buf[i] = buf[i];
    s->buf_size = size;
}

void lzma_sha256_finish(lzma_sha256_state *s, uint8_t out[32])
{
    uint64_t bits = s->size * 8;
    uint8_t pad = 0x80;
    lzma_sha256_update(s, &pad, 1);
    pad = 0;
    while (s->buf_size != 56)
        lzma_sha256_update(s, &pad, 1);
    uint8_t lenbuf[8];
    for (int i = 0; i < 8; i++)
        lenbuf[i] = (uint8_t)(bits >> (56 - 8*i));
    // append length manually without affecting s->size
    for (int i = 0; i < 8; i++) s->buf[s->buf_size++] = lenbuf[i];
    sha256_transform(s, s->buf);
    for (int i = 0; i < 8; i++) {
        out[i*4]   = (uint8_t)(s->state[i] >> 24);
        out[i*4+1] = (uint8_t)(s->state[i] >> 16);
        out[i*4+2] = (uint8_t)(s->state[i] >> 8);
        out[i*4+3] = (uint8_t)(s->state[i]);
    }
}

