#ifndef XZ_LZMA_DECODER_H
#define XZ_LZMA_DECODER_H

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

#define LZMA_STATES 12
#define LZMA_POS_STATES_MAX 16
#define LZMA_MATCH_LEN_MIN 2
#define LZMA_MATCH_LEN_MAX 273
#define LZMA_DIST_STATES 4
#define LZMA_ALIGN_BITS 4
#define LZMA_ALIGN_SIZE 16
#define LZMA_LITERAL_CODERS_MAX 16
#define LZMA_LITERAL_CODER_SIZE 0x300
#define LZMA_PROBS_SIZE (1846 + (1 << 4) * LZMA_LITERAL_CODER_SIZE)

typedef struct {
    const uint8_t *in;
    size_t in_pos;
    size_t in_size;
    uint32_t range;
    uint32_t code;
    uint8_t init_bytes_left; // bytes still needed for init (5)
    bool init_done;
    bool corrupt;
} lzma_rc_dec;

// The LZMA probability model
typedef struct {
    uint16_t probs[LZMA_PROBS_SIZE]; // layout below
    uint32_t state;
    uint32_t rep0, rep1, rep2, rep3;
    uint32_t lc, lp, pb;
    uint32_t lp_mask, pb_mask;
    uint32_t literal_context_bits, literal_pos_mask;
} lzma_lzma_dec;

// Dictionary (circular)
typedef struct {
    uint8_t *buf;
    size_t size;    // dict size
    size_t pos;     // current write pos
    size_t full;    // how much history is valid (<= size)
    bool need_reset;
} lzma_dict;

typedef enum {
    LZMA_DEC_OK = 0,        // chunk/stream finished cleanly
    LZMA_DEC_NEED_INPUT,    // ran out of input mid-stream (caller decides: EOF error or refill)
    LZMA_DEC_CORRUPT,
    LZMA_DEC_UNSUPPORTED,
} lzma_dec_ret;

// offsets into probs[]
#define P_IS_MATCH 0
#define P_IS_REP (P_IS_MATCH + LZMA_STATES * LZMA_POS_STATES_MAX)
#define P_IS_REP_G0 (P_IS_REP + LZMA_STATES)
#define P_IS_REP_G1 (P_IS_REP_G0 + LZMA_STATES)
#define P_IS_REP_G2 (P_IS_REP_G1 + LZMA_STATES)
#define P_IS_REP_G0_LONG (P_IS_REP_G2 + LZMA_STATES)
#define P_POS_SLOT (P_IS_REP_G0_LONG + LZMA_STATES * LZMA_POS_STATES_MAX)
#define P_SPEC_POS (P_POS_SLOT + LZMA_DIST_STATES * 64)
#define P_ALIGN (P_SPEC_POS + 1 + 115)  // kNumFullDistances - kEndPosModelIndex = 114, +1
#define P_LEN_CHOICE (P_ALIGN + LZMA_ALIGN_SIZE)
#define P_LEN_CHOICE2 (P_LEN_CHOICE + 1)
#define P_LEN_LOW (P_LEN_CHOICE2 + 1)
#define P_LEN_MID (P_LEN_LOW + LZMA_POS_STATES_MAX * 8)
#define P_LEN_HIGH (P_LEN_MID + LZMA_POS_STATES_MAX * 8)
#define P_LITERAL (P_LEN_HIGH + 256)

void lzma_lzma_dec_reset(lzma_lzma_dec *d, uint32_t lc, uint32_t lp, uint32_t pb);
void lzma_rc_dec_init(lzma_rc_dec *rc);

// Decode exactly one LZMA chunk producing up to out_limit bytes into dict,
// reading compressed data from rc->in. If uncomp_size_known is false,
// decoding stops at end-of-stream marker (LZMA1 only).
// Returns LZMA_DEC_OK when the chunk ended properly (size reached or marker).
lzma_dec_ret lzma_lzma_decode(lzma_lzma_dec *d, lzma_rc_dec *rc, lzma_dict *dict,
        bool uncomp_size_known, uint64_t uncomp_size,
        bool eopm_allowed, bool *eopm_found, uint64_t *produced);

#endif

