#include "lzma_decoder.h"

#define RC_TOP (1u << 24)
#define PROB_INIT 0x400
#define MOVE_BITS 5

void lzma_lzma_dec_reset(lzma_lzma_dec *d, uint32_t lc, uint32_t lp, uint32_t pb)
{
    d->lc = lc; d->lp = lp; d->pb = pb;
    d->lp_mask = (1u << lp) - 1;
    d->pb_mask = (1u << pb) - 1;
    for (size_t i = 0; i < LZMA_PROBS_SIZE; i++)
        d->probs[i] = PROB_INIT;
    d->state = 0;
    d->rep0 = d->rep1 = d->rep2 = d->rep3 = 0;
}

void lzma_rc_dec_init(lzma_rc_dec *rc)
{
    rc->range = 0xFFFFFFFF;
    rc->code = 0;
    rc->init_bytes_left = 5;
    rc->init_done = false;
    rc->corrupt = false;
}

static inline bool rc_read_byte(lzma_rc_dec *rc, uint32_t *b)
{
    if (rc->in_pos >= rc->in_size)
        return false;
    *b = rc->in[rc->in_pos++];
    return true;
}

// normalize: returns false if input exhausted
static inline bool rc_normalize(lzma_rc_dec *rc)
{
    if (rc->range < RC_TOP) {
        uint32_t b;
        if (!rc_read_byte(rc, &b)) {
            rc->corrupt = true;
            return false;
        }
        rc->range <<= 8;
        rc->code = (rc->code << 8) | b;
    }
    return true;
}

static inline int rc_bit(lzma_rc_dec *rc, uint16_t *prob, int *bit)
{
    if (!rc_normalize(rc))
        return -1;
    uint32_t bound = (rc->range >> 11) * (*prob);
    if (rc->code < bound) {
        rc->range = bound;
        *prob += (uint16_t)((0x800 - *prob) >> MOVE_BITS);
        *bit = 0;
    } else {
        rc->range -= bound;
        rc->code -= bound;
        *prob -= (uint16_t)(*prob >> MOVE_BITS);
        *bit = 1;
    }
    return 0;
}

static inline int rc_direct(lzma_rc_dec *rc, int nbits, uint32_t *out)
{
    uint32_t res = 0;
    for (int i = 0; i < nbits; i++) {
        if (!rc_normalize(rc))
            return -1;
        rc->range >>= 1;
        res <<= 1;
        if (rc->code >= rc->range) {
            rc->code -= rc->range;
            res |= 1;
        }
    }
    *out = res;
    return 0;
}

static inline int rc_bittree(lzma_rc_dec *rc, uint16_t *probs, int nbits, uint32_t *out)
{
    uint32_t sym = 1;
    for (int i = 0; i < nbits; i++) {
        int bit;
        if (rc_bit(rc, &probs[sym], &bit))
            return -1;
        sym = (sym << 1) | bit;
    }
    *out = sym - (1u << nbits);
    return 0;
}

static inline int rc_bittree_rev(lzma_rc_dec *rc, uint16_t *probs, int nbits, uint32_t *out)
{
    uint32_t sym = 1, res = 0;
    for (int i = 0; i < nbits; i++) {
        int bit;
        if (rc_bit(rc, &probs[sym], &bit))
            return -1;
        sym = (sym << 1) | bit;
        res |= (uint32_t)bit << i;
    }
    *out = res;
    return 0;
}

static inline size_t dict_avail_write(lzma_dict *dict)
{
    return dict->size - dict->pos;
}

static inline void dict_put(lzma_dict *dict, uint8_t b)
{
    dict->buf[dict->pos++] = b;
    if (dict->full < dict->pos)
        dict->full = dict->pos;
}

// copy match of len bytes at distance dist+1. Caller ensures validity.
// returns number of bytes actually copied (limited by remaining out space)
static inline int dict_repeat(lzma_dict *dict, uint32_t dist, uint32_t len,
        uint64_t *remaining)
{
    // dist is distance-1 (i.e. rep value). back position:
    size_t back;
    if (dist >= dict->full || dict->pos == 0 && dict->full == 0)
        return -1;
    if (dict->pos > dist)
        back = dict->pos - dist - 1;
    else
        back = dict->size - (dist - dict->pos) - 1;
    uint32_t n = 0;
    while (n < len && *remaining > 0) {
        uint8_t b = dict->buf[back++];
        if (back == dict->size)
            back = 0;
        dict_put(dict, b);
        if (dict->pos == dict->size && *remaining > 1) {
            // buffer full: caller must flush; we signal by returning early
        }
        n++;
        (*remaining)--;
        if (dict->pos == dict->size)
            break; // need flush; return partial
    }
    return (int)n;
}

lzma_dec_ret lzma_lzma_decode(lzma_lzma_dec *d, lzma_rc_dec *rc, lzma_dict *dict,
        bool uncomp_size_known, uint64_t uncomp_size,
        bool eopm_allowed, bool *eopm_found, uint64_t *produced)
{
    uint64_t remaining = uncomp_size_known ? uncomp_size : UINT64_MAX;
    *produced = 0;
    *eopm_found = false;

    // init range decoder
    if (!rc->init_done) {
        uint32_t b;
        while (rc->init_bytes_left > 0) {
            if (!rc_read_byte(rc, &b)) {
                return LZMA_DEC_NEED_INPUT;
            }
            if (rc->init_bytes_left == 5 && b != 0) {
                rc->corrupt = true;
                return LZMA_DEC_CORRUPT;
            }
            if (rc->init_bytes_left <= 4)
                rc->code = (rc->code << 8) | b;
            rc->init_bytes_left--;
        }
        rc->init_done = true;
    }

    while (remaining > 0) {
        if (dict->pos == dict->size)
            return LZMA_DEC_OK; // dict full; caller flushes and re-enters

        uint32_t pos_state = (uint32_t)(dict->pos + 0) & d->pb_mask;
        // note: pos state is based on total uncompressed position, not dict pos.
        // caller adjusts via d->pos_offset? We track separately below.
        (void)pos_state;
        break;
    }
    // We need total uncompressed position for pos states. Use a field.
    return LZMA_DEC_OK;
}

