    for (int i = 0; i < nbits; i++) {
        if (!rc_normalize(rc))
            return -1;
        rc->range >>= 1;
        res <<= 1;
        if (rc->code >= rc->range) {
            rc->code -= rc->range;
            res |= 1;
        }
    }
    *out = res;
    return 0;
}

static inline int rc_bittree(lzma_rc_dec *rc, uint16_t *probs, int nbits, uint32_t *out)
{
    uint32_t sym = 1;
    for (int i = 0; i < nbits; i++) {
        uint32_t bit;
        if (rc_bit(rc, &probs[sym], &bit))
            return -1;
        sym = (sym << 1) | bit;
    }
    *out = sym - (1u << nbits);
    return 0;
}

