    for (int i = 0; i < nbits; i++) {
        uint32_t bit;
        if (rc_bit(rc, &probs[sym], &bit))
            return -1;
        sym = (sym << 1) | bit;
        res |= (uint32_t)bit << i;
    }
    *out = res;
    return 0;
