#ifndef XZ_LZMA_ENCODER_H
#define XZ_LZMA_ENCODER_H

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

#define MATCH_LEN_MIN 2
#define MATCH_LEN_MAX 273
#define NUM_STATES 12
#define POS_STATES_MAX 16
#define DIST_STATES 4
#define DIST_SLOTS 64
#define DIST_MODEL_START 4
#define DIST_MODEL_END 14
#define FULL_DISTANCES 128
#define ALIGN_BITS 4
#define ALIGN_SIZE 16
#define LEN_LOW_SYMBOLS 8
#define LEN_MID_SYMBOLS 8
#define LEN_HIGH_SYMBOLS 256
#define LEN_SYMBOLS (LEN_LOW_SYMBOLS + LEN_MID_SYMBOLS + LEN_HIGH_SYMBOLS)
#define LITERAL_CODER_SIZE 0x300
#define RC_TOP (1u << 24)

// Match finder modes
#define MF_HC3 0x03
#define MF_HC4 0x04
#define MF_BT2 0x12
#define MF_BT3 0x13
#define MF_BT4 0x14

typedef struct {
    uint16_t len;
    uint32_t dist;   // 0-based (actual distance - 1)
} lzma_match;

// ---- Match finder ----
typedef struct {
    const uint8_t *buf;   // whole input
    size_t buf_size;
    uint32_t pos;         // current position (absolute), next byte to encode
    uint32_t dict_size;
    uint32_t cyclic_size; // dict_size + 1
    uint32_t hash_mask;
    uint32_t *hash;
    uint32_t *son;
